341	    /**
342	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
343	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
344	     * upper-cased, and common street-type abbreviations are expanded token-by-token
345	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
346	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
347	     * used for every address comparison (household-duplicate detection and the shared household id).
348	     */
349	    private static String normalizeAddress(String value) {
350	        if (value == null) {
351	            return "";
352	        }
353	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
354	        if (collapsed.isEmpty()) {
355	            return "";
356	        }
357	        String[] tokens = collapsed.split(" ");
358	        StringBuilder sb = new StringBuilder();
359	        for (int i = 0; i < tokens.length; i++) {
360	            if (i > 0) {
361	                sb.append(' ');
362	            }
363	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
364	        }
365	        return sb.toString();
366	    }
